pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am) public {
        vm.assume(am > 0 && am < 100 ether);
        vm.deal(address(this), am);
        uint256 balBefore = address(c).balance;

        // Send enough ether so balance >= MinSum and >= am
        c.Put{value: am}(block.timestamp);

        // Skip to after unlockTime
