pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount, uint256 delay) public {
        // Bound parameters to avoid overflow/time issues
        vm.assume(amount <= 100 ether);
        vm.assume(delay < 365 days);

        // Deposit ether as a random user to make Collect possible
        address user = address(0x1234);
        vm.deal(user, amount);
        vm.prank(user);
        c.Put{value: amount}(block.timestamp + delay);

        // Record state before Collect
        uint256 contractBalanceBefore = address(c).balance;
        uint256 userBalanceBefore = c.Acc(user).balance;

        // Attempt Collect - may revert if conditions not met
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, amount));

        // Assert total ether invariant: deposited amount should equal sum of user balance + contract balance
        // The invariant holds regardless of whether Collect reverted, because ether is only moved between user and contract
        uint256 totalEther = contractBalanceBefore + userBalanceBefore;
        uint256 contractBalanceAfter = address(c).balance;
        uint256 userBalanceAfter = c.Acc(user).balance;
        assertTrue(contractBalanceAfter + userBalanceAfter == totalEther, "Invariant violated: total ether changed");
    }
}

