pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user1, address user2, uint256 deposit1, uint256 deposit2, uint256 collectAmt) public {
        // Bound inputs to reasonable values
        deposit1 = bound(deposit1, 1 ether, 100 ether);
        deposit2 = bound(deposit2, 1 ether, 100 ether);
        collectAmt = bound(collectAmt, 0.5 ether, 1 ether);
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2);

        // Fund users
        vm.deal(user1, deposit1);
        vm.deal(user2, deposit2);

        // User1 deposits
        vm.prank(user1);
        c.Put(block.timestamp + 1 days);
        // User2 deposits
        vm.prank(user2);
        c.Put(block.timestamp + 1 days);

        // Warp past unlock time
        vm.warp(block.timestamp + 2 days);

        // Record state before Collect
        uint256 contractBalanceBefore = address(c).balance;
        uint256 user1BalanceBefore = c.Acc(user1).balance;
        uint256 user2BalanceBefore = c.Acc(user2).balance;

        // This test checks invariants after Collect call; here user1 collects
        vm.prank(user1);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // After Collect, compute sums
        uint256 contractBalanceAfter = address(c).balance;
        uint256 user1BalanceAfter = c.Acc(user1).balance;
        uint256 user2BalanceAfter = c.Acc(user2).balance;
        uint256 sumBefore = contractBalanceBefore + user1BalanceBefore + user2BalanceBefore;
        uint256 sumAfter = contractBalanceAfter + user1BalanceAfter + user2BalanceAfter;

        // The sum should remain unchanged (no ether created or destroyed)
        assertTrue(sumBefore == sumAfter, "Sum of contract balance and user balances changed");
    }
}

