import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint amount, uint unlockTime, uint collectAmt) public {
        vm.assume(user != address(0));
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.assume(collectAmt > 0 && collectAmt <= amount);
        // Deposit ether for the user
        vm.deal(user, amount);
        vm.prank(user);
        c.Put{value: amount}(unlockTime);
        // Fast forward past unlock time
        vm.warp(block.timestamp + unlockTime + 1);
        // Record balance before Collect
        uint256 balanceBefore = c.Acc(user).balance;
