pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount, uint256 unlockTime) public {
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1 ether, 10 ether);
        collectAmount = bound(collectAmount, 0, depositAmount);
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 1000);

        // Track total ether deposited
        uint256 totalDeposited = 0;

        // Deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put{value: depositAmount}(unlockTime);
        totalDeposited += depositAmount;

        // Fast forward to after unlock time
        vm.warp(unlockTime + 1);

        // Sum user balances before Collect
        (uint256 balanceBefore, ) = c.Acc(caller);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Sum user balances after Collect
        (uint256 balanceAfter, ) = c.Acc(caller);

        // Compute the invariant: total ether in contract + sum of all user balances should equal total deposited
        uint256 contractEther = address(c).balance;
        uint256 sumUserBalances = balanceAfter;
        // For simplicity, we only track this caller's balance; but the invariant holds per user because no other user deposits
        uint256 invariant = contractEther + sumUserBalances;

        // The invariant should equal totalDeposited (minus what was sent out, but that's captured in contractEther)
        // Actually, if Collect succeeded, totalDeposited should be invariant minus collected amount? No.
        // Better: totalDeposited = contractEther + sumUserBalances + (amount collected if success, else 0)
        // But if reentrancy happened, this could be violated.
        uint256 collected = success ? collectAmount : 0;
        assertTrue(invariant + collected == totalDeposited, "Invariant violated");
    }
}

