pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 withdrawAmt, uint256 depositTime) public {
        vm.assume(amount >= 1 ether && amount <= 100 ether);
        vm.assume(withdrawAmt >= 1 ether && withdrawAmt <= amount);
        depositTime = bound(depositTime, block.timestamp, block.timestamp + 1000000);

        // Deposit funds
        vm.deal(address(this), amount);
        c.Put(depositTime);

        // Move time forward to allow withdrawal
        vm.warp(depositTime + 1);

        // Record pre-withdrawal balance
        uint256 preBalance = address(this).balance;

        // Attempt withdrawal
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, withdrawAmt));

        // After call, the contract's internal state can be observed
        // The invariant: If the withdrawal succeeded, the contract's balance should decrease by withdrawAmt + 1 (bug)
        // In the correct version it only decreases by withdrawAmt
        // We express a property that holds for the correct version and fails for the buggy one:
        // The contract's balance change (initial - final) should be exactly the amount withdrawn.
        // (Ignoring the extra 1 wei subtraction in the bug)

        uint256 balanceAfter = address(c).balance;
        uint256 contractReceived = amount;
        uint256 contractWithdrawn = success ? withdrawAmt : 0;
        uint256 expectedBalance = contractReceived - contractWithdrawn;

        // The ground truth: buggy version subtracts an extra 1 wei
        // So the invariant: balanceAfter == expectedBalance (true for correct, false for buggy when success)
        // But we must handle the case when withdrawal fails (then balance stays)
        if (success) {
            assertTrue(balanceAfter == expectedBalance, "Balance mismatch");
        } else {
            assertTrue(balanceAfter == contractReceived, "Withdrawal failed");
        }
    }
}

