pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, uint256 initialBalance, uint256 unlockTime) public {
        // Bound inputs to realistic ranges
        vm.assume(_am <= 1e20);
        vm.assume(initialBalance >= _am);
        vm.assume(initialBalance >= 1 ether);
        vm.assume(unlockTime <= type(uint256).max - 100);

        // Set up caller with initial balance
        address caller = address(0x1234);
        vm.deal(caller, initialBalance);

        // Fund the contract with enough balance for the caller
        vm.deal(address(c), initialBalance);

        // Set up the caller's account in the contract
        vm.prank(caller);
        c.Put{value: initialBalance}(unlockTime);

        // Record caller's balance before Collect
        uint256 beforeBalance = caller.balance;

        // Advance time past unlockTime
        vm.warp(unlockTime + 1);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.Collect.selector, _am));

        // Record caller's balance after
        uint256 afterBalance = caller.balance;

        // Rule: if Collect succeeded, caller's balance increased by exactly _am
        // In reference: afterBalance - beforeBalance == _am
        // In buggy version: afterBalance - beforeBalance == _am - 1 (because extra 1 wei subtracted from contract balance, not sent to caller)
        // Actually, for the buggy version, caller receives _am wei but contract deducts _am+1 from acc.balance
        // The caller's balance change is still _am (since they receive _am wei)
        // Wait: the bug only affects acc.balance, not the amount sent. So the caller's balance change is the same in both versions.
        // Let's check: In Collect, the external call sends _am wei to msg.sender, so caller's balance increases by _am.
        // The buggy version also sends _am wei (same call), so caller's balance change is identical.
        // The difference is in acc.balance: reference subtracts _am, buggy subtracts _am+1.
        // So we need a rule about acc.balance, not about caller's balance.
        // But we cannot read acc.balance directly because it's private? No, Acc is public mapping, so we can read Acc(msg.sender).

        // Let's use the public getter for Acc
        (uint256 unlockTimeAcc, uint256 balanceAcc) = c.Acc(caller);

        // Rule: if Collect succeeded, balance in Acc decreased by exactly _am
        // Reference: after Collect, acc.balance = initialBalance - _am
        // Buggy: after Collect, acc.balance = initialBalance - _am - 1
        // So assert that balanceAcc == initialBalance - _am
        assertTrue(!success || balanceAcc == initialBalance - _am, "Rule failed");
    }
}

