pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, uint256 _unlockTime, uint256 _initialBalance) public {
        vm.assume(_am > 0 && _am <= _initialBalance);
        _initialBalance = bound(_initialBalance, 1 ether, 1000 ether);
        _unlockTime = bound(_unlockTime, 1, 1000000);

        // Fund the contract so it has enough balance
        vm.deal(address(c), _initialBalance);

        // Create a user and deposit so they have balance
        address user = address(0x1234);
        vm.deal(user, _initialBalance);

        // Set up: user puts in some amount to create a balance in the contract
        vm.prank(user);
        (bool successPut, ) = address(c).call{value: _initialBalance}(abi.encodeWithSignature("Put(uint256)", _unlockTime));
        require(successPut, "Put failed");

        // Warp to after unlock time
        vm.warp(_unlockTime + 1);

        // Record user balance before Collect
        uint256 balanceBefore = user.balance;

        // Call Collect
        vm.prank(user);
        (bool successCollect, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        if (successCollect) {
            uint256 balanceAfter = user.balance;
            // The rule: balance decrease must equal exactly _am (not _am + 1)
            assertTrue(balanceBefore - balanceAfter == _am, "Balance decreased by more than _am");
        } else {
            // If Collect reverts, no assertion needed
            assertTrue(true);
        }
    }
}

