        // Ensure _am is bounded to a reasonable value
        _am = bound(_am, 1 ether, 10 ether);

        // Deal the contract enough balance
        vm.deal(address(c), 100 ether);

        // First, fund the caller so they have some balance to put in
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);

        // Alice puts in _am plus 1 ether to meet MinSum
        vm.prank(alice);
        c.Put{value: _am + 1 ether}(block.timestamp);

        // Record Alice's balance before Collect
        uint balanceBefore = alice.balance;

