// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am, uint256 seedBalance, uint256 unlockTimeOffset) public {
        // Bound parameters to valid ranges
        am = bound(am, 0, 1e18);
        seedBalance = bound(seedBalance, 1e18, 1e20);
        unlockTimeOffset = bound(unlockTimeOffset, 1, 1000000);

        // Fund the contract with seedBalance
        vm.deal(address(c), seedBalance);

        // Set up the caller's balance in the contract via Put with a future unlock time
        uint256 unlockTime = block.timestamp + unlockTimeOffset;
        vm.prank(address(0x1234));
        (bool successPut, ) = address(c).call{value: am}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        vm.assume(successPut);

        // Ensure the contract balance before Collect
        uint256 balanceBefore = address(c).balance;

        // Call Collect with the same amount am
        vm.prank(address(0x1234));
        (bool successCollect, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        // Only consider successful calls
        vm.assume(successCollect);

        // After a successful Collect, the contract balance should decrease by exactly am
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - am, "Contract balance decrease should equal am");
    }
}
